// Written from scratch for this project; no third-party code.

const ASCII_PUNCT = /[!-\/:-@\[-`{-~]/;
const UNI_PUNCT = /[\p{P}\p{S}]/u;

const ENTITIES = {
  amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: '\u00a0',
  copy: '\u00a9', reg: '\u00ae', trade: '\u2122', mdash: '\u2014',
  ndash: '\u2013', hellip: '\u2026', laquo: '\u00ab', raquo: '\u00bb',
  lsquo: '\u2018', rsquo: '\u2019', ldquo: '\u201c', rdquo: '\u201d',
  times: '\u00d7', divide: '\u00f7', euro: '\u20ac', pound: '\u00a3',
  yen: '\u00a5', cent: '\u00a2', sect: '\u00a7', deg: '\u00b0',
  plusmn: '\u00b1', middot: '\u00b7', para: '\u00b6', frac12: '\u00bd',
  frac14: '\u00bc', frac34: '\u00be',
};

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

