function renderInline(nodes) {
  return nodes
    .map((n) => {
      switch (n.t) {
        case 'text': return esc(n.v);
        case 'delim': return esc(n.ch.repeat(n.count));
        case 'code': return '<code>' + esc(n.v) + '</code>';
        case 'em': return '<em>' + renderInline(n.children) + '</em>';
