// Minimal CommonMark-style Markdown -> HTML renderer (tier S1).
// Written from scratch for this project; no third-party code.

const ASCII_PUNCT = /[!-\/:-@\[-`{-~]/;
const UNI_PUNCT = /[\p{P}\p{S}]/u;

const ENTITIES = {
  amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ',
  copy: '©', reg: '®', trade: '™', mdash: '—',
  ndash: '–', hellip: '…', laquo: '«', raquo: '»',
  lsquo: '‘', rsquo: '’', ldquo: '“', rdquo: '”',
  times: '×', divide: '÷', euro: '€', pound: '£',
  yen: '¥', cent: '¢', sect: '§', deg: '°',
  plusmn: '±', middot: '·', para: '¶', frac12: '½',
  frac14: '¼', frac34: '¾',
};

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function esc(s) {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function isBlank(line) {
  return /^[ \t]*$/.test(line);
}

function leadingSpaces(line) {
  return /^ */.exec(line)[0].length;
}

function expandLeadingTabs(line) {
  let col = 0;
  let out = '';
  let k = 0;
  while (k < line.length && (line[k] === ' ' || line[k] === '\t')) {
    if (line[k] === '\t') {
      const sp = 4 - (col % 4);
      out += ' '.repeat(sp);
      col += sp;
    } else {
      out += ' ';
      col++;
    }
    k++;
  }
  return out + line.slice(k);
}

function decodeEntity(e) {
  // e is the part between '&' and ';' (without them); returns decoded text or null.
  if (e[0] === '#') {
    const hex = e[1] === 'x' || e[1] === 'X';
    const cp = parseInt(e.slice(hex ? 2 : 1), hex ? 16 : 10);
    if (!Number.isFinite(cp) || cp === 0 || cp > 0x10ffff || (cp >= 0xd800 && cp <= 0xdfff)) return '�';
    return String.fromCodePoint(cp);
  }
  return Object.prototype.hasOwnProperty.call(ENTITIES, e) ? ENTITIES[e] : null;
}

// Resolve backslash escapes and entities (used for link destinations/titles/info strings).
function unescapeString(s) {
  return s.replace(/\\([!-\/:-@\[-`{-~])|&(#[xX][0-9a-fA-F]{1,6}|#[0-9]{1,7}|[A-Za-z][A-Za-z0-9]{0,31});/g,
    (m, p, e) => {
      if (p) return p;
      const d = decodeEntity(e);
      return d === null ? m : d;
    });
}

function encodeUrl(u) {
  let r;
  try {
    r = encodeURI(u);
  } catch {
    r = u;
  }
  return r.replace(/%25([0-9A-Fa-f]{2})/g, '%$1');
}

// ---------------------------------------------------------------------------
// Block parsing
// ---------------------------------------------------------------------------

const FENCE_OPEN = /^( {0,3})(`{3,}|~{3,})(.*)$/;
const FENCE_CLOSE = /^ {0,3}(`{3,}|~{3,})[ \t]*$/;
const ATX = /^ {0,3}(#{1,6})(?:[ \t]+(.*))?$/;
const HR = /^ {0,3}([-*_])(?:[ \t]*\1){2,}[ \t]*$/;
const SETEXT = /^ {0,3}(=+|-+)[ \t]*$/;
const QUOTE = /^ {0,3}>/;
const LIST_RE = /^( {0,3})([-+*]|(\d{1,9})([.)]))(?=[ \t]|$)(.*)$/;

function isHr(line) {
  return HR.test(line);
}

function listStart(line) {
  const m = LIST_RE.exec(line);
  if (!m) return null;
  const leading = m[1].length;
  const marker = m[2];
  const rest0 = m[5];
  const spaces = /^[ \t]*/.exec(rest0)[0].length;
  const empty = rest0.trim() === '';
  let contentIndent;
  let rest;
  if (empty) {
    contentIndent = leading + marker.length + 1;
    rest = '';
  } else if (spaces >= 5) {
    contentIndent = leading + marker.length + 1;
    rest = rest0.slice(1);
  } else {
    contentIndent = leading + marker.length + spaces;
    rest = rest0.slice(spaces);
  }
  const ordered = m[3] !== undefined;
  return {
    ordered,
    delim: ordered ? m[4] : marker,
    start: ordered ? parseInt(m[3], 10) : 1,
    contentIndent,
    rest,
    empty,
  };
}

function isBlockStart(line, inPara) {
  if (FENCE_OPEN.test(line) && !/`/.test(FENCE_OPEN.exec(line)[3]) || /^ {0,3}~~~/.test(line)) return true;
  if (ATX.test(line)) return true;
  if (isHr(line)) return true;
  if (QUOTE.test(line)) return true;
  const ls = listStart(line);
  if (ls && (!inPara || (!ls.empty && (!ls.ordered || ls.start === 1)))) return true;
  return false;
}

function parseList(lines, i) {
  const first = listStart(lines[i]);
  const n = lines.length;
  const items = [];
  while (i < n) {
    const ls = listStart(lines[i]);
    if (!ls || isHr(lines[i]) || ls.ordered !== first.ordered || ls.delim !== first.delim) break;
    const itemLines = [ls.rest];
    let j = i + 1;
    while (j < n) {
      const l = lines[j];
      if (isBlank(l)) {
        if (ls.empty && itemLines.length === 1) break;
        itemLines.push('');
        j++;
        continue;
      }
      if (leadingSpaces(l) >= ls.contentIndent) {
        itemLines.push(l.slice(ls.contentIndent));
        j++;
        continue;
      }
      // Lazy paragraph continuation.
      const last = itemLines[itemLines.length - 1];
      if (last !== '' && !isBlockStart(l, true)) {
        itemLines.push(l.replace(/^ +/, ''));
        j++;
        continue;
      }
      break;
    }
    let trailing = 0;
    while (itemLines.length && itemLines[itemLines.length - 1] === '') {
      itemLines.pop();
      trailing++;
    }
    items.push({ children: parseBlocks(itemLines), trailingBlank: trailing > 0 });
    i = j;
  }
  const loose =
    items.some((it, k) => k < items.length - 1 && it.trailingBlank) ||
    items.some((it) => it.children.spaced);
  return {
    node: { t: 'list', ordered: first.ordered, start: first.start, items, loose },
    next: i,
  };
}

function parseBlocks(lines) {
  const out = [];
  out.spaced = false;
  const n = lines.length;
  let i = 0;
  let sawBlank = false;

  while (i < n) {
    const line = lines[i];
    if (isBlank(line)) {
      sawBlank = true;
      i++;
      continue;
    }
    if (sawBlank && out.length) out.spaced = true;
    sawBlank = false;

    // Indented code block.
    if (leadingSpaces(line) >= 4) {
      const body = [];
      let j = i;
      while (j < n) {
        const l = lines[j];
        if (isBlank(l)) {
          body.push('');
          j++;
          continue;
        }
        if (leadingSpaces(l) >= 4) {
          body.push(l.slice(4));
          j++;
          continue;
        }
        break;
      }
      let k = body.length;
      while (k > 0 && body[k - 1] === '') k--;
      out.push({ t: 'code', info: '', text: body.slice(0, k).map((x) => x + '\n').join('') });
      i += k;
      continue;
    }

    // Fenced code block.
    const fm = FENCE_OPEN.exec(line);
    if (fm && !(fm[2][0] === '`' && fm[3].includes('`'))) {
      const fence = fm[2];
      const fInd = fm[1].length;
      const info = unescapeString(fm[3].trim());
      const body = [];
      let j = i + 1;
      while (j < n) {
        const l = lines[j];
        const cm = FENCE_CLOSE.exec(l);
        if (cm && cm[1][0] === fence[0] && cm[1].length >= fence.length) break;
        body.push(l.replace(new RegExp('^ {0,' + fInd + '}'), ''));
        j++;
      }
      out.push({ t: 'code', info, text: body.map((l) => l + '\n').join('') });
      i = j + 1;
      continue;
    }

    // ATX heading.
    const am = ATX.exec(line);
    if (am) {
      let text = am[2] || '';
      text = text.replace(/[ \t]+#+[ \t]*$/, '').replace(/^#+[ \t]*$/, '').trim();
      out.push({ t: 'heading', level: am[1].length, text });
      i++;
      continue;
    }

    // Thematic break.
    if (isHr(line)) {
      out.push({ t: 'hr' });
      i++;
      continue;
    }

    // Blockquote.
    if (QUOTE.test(line)) {
      const inner = [];
      let j = i;
      while (j < n) {
        const l = lines[j];
        if (QUOTE.test(l)) {
          inner.push(l.replace(/^ {0,3}> ?/, ''));
          j++;
          continue;
        }
        const lastInner = inner[inner.length - 1];
        if (
          !isBlank(l) && lastInner !== undefined && !isBlank(lastInner) &&
          !isBlockStart(l, true) &&
          !FENCE_OPEN.test(lastInner) && !ATX.test(lastInner) && !isHr(lastInner)
        ) {
          inner.push(l);
          j++;
          continue;
        }
        break;
      }
      out.push({ t: 'quote', children: parseBlocks(inner) });
      i = j;
      continue;
    }

    // List.
    if (listStart(line)) {
      const r = parseList(lines, i);
      out.push(r.node);
      i = r.next;
      continue;
    }

    // Paragraph (possibly a setext heading).
    const pl = [line.replace(/^ +/, '')];
    let j = i + 1;
    let setextLevel = 0;
    while (j < n) {
      const l = lines[j];
      if (isBlank(l)) break;
      const sm = SETEXT.exec(l);
      if (sm) {
        setextLevel = sm[1][0] === '=' ? 1 : 2;
        j++;
        break;
      }
      if (isBlockStart(l, true)) break;
      pl.push(l.replace(/^ +/, ''));
      j++;
    }
    if (setextLevel) {
      out.push({ t: 'heading', level: setextLevel, text: pl.join('\n').trim() });
    } else {
      out.push({ t: 'para', text: pl.join('\n').trimEnd() });
    }
    i = j;
  }
  return out;
}

// ---------------------------------------------------------------------------
// Inline parsing
// ---------------------------------------------------------------------------

// Parses "(dest "title")" starting at s[p] === '('. Returns null on failure.
function parseLinkTail(s, p) {
  let q = p + 1;
  const skipWs = () => {
    while (q < s.length && (s[q] === ' ' || s[q] === '\t' || s[q] === '\n')) q++;
  };
  skipWs();
  let dest;
  if (s[q] === '<') {
    let k = q + 1;
    let d = '';
    while (k < s.length && s[k] !== '>' && s[k] !== '\n' && s[k] !== '<') {
      if (s[k] === '\\' && k + 1 < s.length) {
        d += s[k] + s[k + 1];
        k += 2;
        continue;
      }
      d += s[k];
      k++;
    }
    if (s[k] !== '>') return null;
    dest = d;
    q = k + 1;
  } else {
    let k = q;
    let depth = 0;
    while (k < s.length) {
      const c = s[k];
      if (c === '\\' && k + 1 < s.length && ASCII_PUNCT.test(s[k + 1])) {
        k += 2;
        continue;
      }
      if (c === '(') {
        depth++;
      } else if (c === ')') {
        if (depth === 0) break;
        depth--;
      } else if (c === ' ' || c === '\t' || c === '\n' || c.charCodeAt(0) < 32) {
        break;
      }
      k++;
    }
    if (depth !== 0) return null;
    dest = s.slice(q, k);
    q = k;
  }
  const before = q;
  skipWs();
  let title = null;
  if (q > before && q < s.length && '"\'('.includes(s[q])) {
    const open = s[q];
    const close = open === '(' ? ')' : open;
    let k = q + 1;
    while (k < s.length && s[k] !== close) {
      if (s[k] === '\\' && k + 1 < s.length) {
        k += 2;
        continue;
      }
      k++;
    }
    if (k >= s.length) return null;
    title = s.slice(q + 1, k);
    q = k + 1;
    skipWs();
  }
  if (s[q] !== ')') return null;
  return {
    dest: unescapeString(dest),
    title: title === null || title === '' ? null : unescapeString(title),
    end: q + 1,
  };
}

function flanking(s, start, end) {
  const before = start > 0 ? s[start - 1] : '\n';
  const after = end < s.length ? s[end] : '\n';
  const wsB = /\s/.test(before);
  const wsA = /\s/.test(after);
  const pB = UNI_PUNCT.test(before);
  const pA = UNI_PUNCT.test(after);
  const left = !wsA && (!pA || wsB || pB);
  const right = !wsB && (!pB || wsA || pA);
  return { left, right, pB, pA };
}

function parseInlines(s) {
  const nodes = [];
  const brackets = [];
  let buf = '';
  let i = 0;
  const flush = () => {
    if (buf) {
      nodes.push({ t: 'text', v: buf });
      buf = '';
    }
  };
  const markerToText = (br) => {
    const idx = nodes.indexOf(br);
    if (idx >= 0) nodes[idx] = { t: 'text', v: br.image ? '![' : '[' };
  };

  while (i < s.length) {
    const ch = s[i];

    if (ch === '\\') {
      if (s[i + 1] === '\n') {
        flush();
        nodes.push({ t: 'br' });
        i += 2;
        continue;
      }
      if (i + 1 < s.length && ASCII_PUNCT.test(s[i + 1])) {
        buf += s[i + 1];
        i += 2;
        continue;
      }
      buf += '\\';
      i++;
      continue;
    }

    if (ch === '`') {
      let r = i;
      while (s[r] === '`') r++;
      const n = r - i;
      let j = r;
      let found = -1;
      while (true) {
        const k = s.indexOf('`', j);
        if (k < 0) break;
        let e = k;
        while (s[e] === '`') e++;
        if (e - k === n) {
          found = k;
          break;
        }
        j = e;
      }
      if (found >= 0) {
        let content = s.slice(r, found).replace(/\n/g, ' ');
        if (content.length >= 2 && content[0] === ' ' && content[content.length - 1] === ' ' && /[^ ]/.test(content)) {
          content = content.slice(1, -1);
        }
        flush();
        nodes.push({ t: 'code', v: content });
        i = found + n;
      } else {
        buf += '`'.repeat(n);
        i = r;
      }
      continue;
    }

    if (ch === '&') {
      const m = /^&(#[xX][0-9a-fA-F]{1,6}|#[0-9]{1,7}|[A-Za-z][A-Za-z0-9]{0,31});/.exec(s.slice(i, i + 40));
      if (m) {
        const d = decodeEntity(m[1]);
        if (d !== null) {
          buf += d;
          i += m[0].length;
          continue;
        }
      }
      buf += '&';
      i++;
      continue;
    }

    if (ch === '*' || ch === '_') {
      let j = i;
      while (s[j] === ch) j++;
      const f = flanking(s, i, j);
      let canOpen;
      let canClose;
      if (ch === '*') {
        canOpen = f.left;
        canClose = f.right;
      } else {
        canOpen = f.left && (!f.right || f.pB);
        canClose = f.right && (!f.left || f.pA);
      }
      flush();
      nodes.push({ t: 'delim', ch, count: j - i, origCount: j - i, canOpen, canClose });
      i = j;
      continue;
    }

    if (ch === '!' && s[i + 1] === '[') {
      flush();
      const br = { t: 'bracket', image: true, active: true };
      brackets.push(br);
      nodes.push(br);
      i += 2;
      continue;
    }

    if (ch === '[') {
      flush();
      const br = { t: 'bracket', image: false, active: true };
      brackets.push(br);
      nodes.push(br);
      i++;
      continue;
    }

    if (ch === ']') {
      flush();
      const br = brackets.pop();
      if (!br) {
        buf += ']';
        i++;
        continue;
      }
      if (!br.active) {
        markerToText(br);
        buf += ']';
        i++;
        continue;
      }
      const tail = parseLinkTail(s, i + 1);
      if (!tail) {
        markerToText(br);
        buf += ']';
        i++;
        continue;
      }
      const idx = nodes.indexOf(br);
      const children = nodes.splice(idx + 1);
      nodes.pop(); // remove the opener marker
      processEmphasis(children);
      nodes.push({
        t: br.image ? 'image' : 'link',
        href: tail.dest,
        title: tail.title,
        children,
      });
      if (!br.image) {
        for (const b of brackets) if (!b.image) b.active = false;
      }
      i = tail.end;
      continue;
    }

    if (ch === '\n') {
      const m = / */.exec(buf.match(/ *$/)[0] ? buf : '')[0];
      const trailing = buf.match(/ *$/)[0];
      buf = buf.slice(0, buf.length - trailing.length);
      flush();
      nodes.push({ t: trailing.length >= 2 ? 'br' : 'softbreak' });
      void m;
      i++;
      while (s[i] === ' ') i++;
      continue;
    }

    buf += ch;
    i++;
  }
  flush();
  return nodes;
}

// CommonMark "process emphasis" over a flat node array (in place).
function processEmphasis(nodes) {
  let ci = 0;
  while (ci < nodes.length) {
    const c = nodes[ci];
    if (c.t !== 'delim' || !c.canClose || c.count === 0) {
      ci++;
      continue;
    }
    let oi = ci - 1;
    let found = false;
    for (; oi >= 0; oi--) {
      const o = nodes[oi];
      if (o.t !== 'delim' || o.ch !== c.ch || !o.canOpen || o.count === 0) continue;
      const odd =
        (o.canClose || c.canOpen) &&
        (o.origCount + c.origCount) % 3 === 0 &&
        !(o.origCount % 3 === 0 && c.origCount % 3 === 0);
      if (odd) continue;
      found = true;
      break;
    }
    if (!found) {
      ci++;
      continue;
    }
    const o = nodes[oi];
    const use = o.count >= 2 && c.count >= 2 ? 2 : 1;
    o.count -= use;
    c.count -= use;
    const inner = nodes.splice(oi + 1, ci - oi - 1);
    nodes.splice(oi + 1, 0, { t: use === 2 ? 'strong' : 'em', children: inner });
    ci = oi + 2;
    if (c.count === 0) nodes.splice(ci, 1);
    if (o.count === 0) {
      nodes.splice(oi, 1);
      ci--;
    }
  }
}

function plainText(nodes) {
  return nodes
    .map((n) => {
      switch (n.t) {
        case 'text': return n.v;
        case 'delim': return n.ch.repeat(n.count);
        case 'code': return n.v;
        case 'em':
        case 'strong':
        case 'link':
        case 'image':
          return plainText(n.children);
        case 'br':
        case 'softbreak':
          return '\n';
        case 'bracket':
          return n.image ? '![' : '[';
        default: return '';
      }
    })
    .join('');
}

function renderInline(nodes) {
  return nodes
    .map((n) => {
      switch (n.t) {
        case 'text': return esc(n.v);
        case 'delim': return esc(n.ch.repeat(n.count));
        case 'code': return '<code>' + esc(n.v) + '</code>';
        case 'em': return '<em>' + renderInline(n.children) + '</em>';
        case 'strong': return '<strong>' + renderInline(n.children) + '</strong>';
        case 'link':
          return '<a href="' + esc(encodeUrl(n.href)) + '"' +
            (n.title !== null ? ' title="' + esc(n.title) + '"' : '') +
            '>' + renderInline(n.children) + '</a>';
        case 'image':
          return '<img src="' + esc(encodeUrl(n.href)) + '" alt="' + esc(plainText(n.children)) + '"' +
            (n.title !== null ? ' title="' + esc(n.title) + '"' : '') + ' />';
        case 'br': return '<br />\n';
        case 'softbreak': return '\n';
        case 'bracket': return esc(n.image ? '![' : '[');
        default: return '';
      }
    })
    .join('');
}

function inline(s) {
  const nodes = parseInlines(s);
  processEmphasis(nodes);
  return renderInline(nodes);
}

// ---------------------------------------------------------------------------
// Block rendering
// ---------------------------------------------------------------------------

// Joins rendered pieces; a tight paragraph emits no trailing newline, so one is
// inserted before any following piece.
function joinPieces(pieces) {
  let s = '';
  for (let k = 0; k < pieces.length; k++) {
    s += pieces[k];
    if (k < pieces.length - 1 && pieces[k] !== '' && !pieces[k].endsWith('\n')) s += '\n';
  }
  return s;
}

function renderBlocks(blocks, tight) {
  const pieces = blocks.map((b) => {
    switch (b.t) {
      case 'para': {
        const html = inline(b.text);
        return tight ? html : '<p>' + html + '</p>\n';
      }
      case 'heading':
        return '<h' + b.level + '>' + inline(b.text) + '</h' + b.level + '>\n';
      case 'code': {
        const word = b.info ? b.info.split(/\s+/)[0] : '';
        const cls = word ? ' class="language-' + esc(word) + '"' : '';
        return '<pre><code' + cls + '>' + esc(b.text) + '</code></pre>\n';
      }
      case 'hr':
        return '<hr />\n';
      case 'quote':
        return '<blockquote>\n' + renderBlocks(b.children, false) + '</blockquote>\n';
      case 'list': {
        const tag = b.ordered ? 'ol' : 'ul';
        const startAttr = b.ordered && b.start !== 1 ? ' start="' + b.start + '"' : '';
        const items = b.items
          .map((it) => '<li>' + joinPieces(renderItemChildren(it.children, !b.loose)) + '</li>\n')
          .join('');
        return '<' + tag + startAttr + '>\n' + items + '</' + tag + '>\n';
      }
      default:
        return '';
    }
  });
  return joinPieces(pieces);
}

function renderItemChildren(children, tight) {
  return children.map((c) => renderBlocks([c], tight));
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

export function render(markdown) {
  const src = String(markdown).replace(/\r\n?/g, '\n').replace(/\0/g, '�');
  const lines = src.split('\n').map(expandLeadingTabs);
  return renderBlocks(parseBlocks(lines), false);
}

